/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDocumentStore } from './src/document-store.js';

function scenario(onHandoff) {
  const store = createDocumentStore({ a: 'A', b: 'B', c: 'C' });
  const renders = [];
  const handoffs = [];
  const nav = createWorkspace({ store, renderDocument: value => renders.push(value), onHandoff: (leaving, navigation) => { handoffs.push(leaving); onHandoff?.(leaving, navigation); } });
  return { store, renders, handoffs, nav };
}
{
  const s = scenario();
  s.nav.open('a'); s.nav.edit('edited'); s.nav.open('b');
  assert.deepEqual(s.handoffs, [{ id: 'a', text: 'edited' }]);
  assert.deepEqual(s.renders.at(-1), { id: 'b', text: 'B' });
  assert.equal(s.store.read('a'), 'edited');
  s.nav.close();
  assert.deepEqual(s.handoffs.at(-1), { id: 'b', text: 'B' });
  s.nav.open('c'); s.nav.dispose();
  assert.equal(s.handoffs.length, 2);
}
{
  const s = scenario((leaving, nav) => { if (leaving.id === 'a') nav.open('c'); });
  s.nav.open('a'); s.nav.open('b');
  assert.deepEqual(s.renders.at(-1), { id: 'c', text: 'C' });
  s.nav.edit('changed');
  assert.equal(s.store.read('c'), 'changed');
  assert.equal(s.store.read('b'), 'B');
}
{
  const s = scenario((leaving, nav) => { if (leaving.id === 'a') nav.close(); });
  s.nav.open('a'); s.nav.open('b');
  assert.equal(s.renders.at(-1), null);
}
console.log('workspace checks passed');
EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { render } from './src/render-workspace.js';
import { createPresenceChannel } from './src/channel.js';
import { createWorkspaceNavigation } from './src/workspace-navigation.js';
for (const mode of ['synchronous', 'deferred']) {
  const result = await render({ token: 'room', bootstrapMode: mode });
  assert.deepEqual(result.presence.events, ['room:bootstrap', 'room:update']);
  assert.deepEqual(result.metrics.events, ['room:update']);
}
const first = createPresenceChannel('first');
const second = createPresenceChannel('second');
const seen = [];
const nav = createWorkspaceNavigation((value, navigation) => {
  seen.push(value);
  if (value === 'first:bootstrap') navigation.select(second);
});
nav.select(first);
first.emitUpdate();
second.emitUpdate();
assert.deepEqual(seen, ['first:bootstrap', 'second:bootstrap', 'second:update']);
nav.hide();
second.emitUpdate();
assert.equal(seen.length, 3);
const reused = createPresenceChannel('reused');
const seenReuse = [];
const navReuse = createWorkspaceNavigation((value, navigation) => {
  seenReuse.push(value);
  if (seenReuse.length === 1) navigation.hide();
});
navReuse.select(reused);
reused.emitUpdate();
navReuse.select(reused);
reused.emitUpdate();
assert.deepEqual(seenReuse, ['reused:bootstrap', 'reused:bootstrap', 'reused:update']);
console.log('presence checks passed');
EOF"

