import assert from 'node:assert/strict';
import { createPresenceChannel } from './src/channel.js';
import { createPresencePanel } from './src/presence-panel.js';
let resolve;
const pending = new Promise((r) => { resolve = r; });
const old = createPresenceChannel('old', { decode: () => pending });
const seen = [];
const panel = createPresencePanel((value) => seen.push(value));
panel.show(old);
panel.show(createPresenceChannel('new'));
resolve('old:bootstrap');
await pending;
await Promise.resolve();
assert.deepEqual(seen, ['new:bootstrap']);
console.log('async selection check passed');
EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDraftStore } from './src/draft-store.js';
import { createReceiptArchive } from './src/receipt-archive.js';
function rig(onSaved = () => {}) {
  const pending = new Map(); let next = 0; const statuses = []; const documents = []; const notices = [];
  const timers = { schedule(fn, delay) { assert.equal(delay, 120); const id = ++next; pending.set(id, fn); return id; }, cancel(id) { pending.delete(id); } };
  const store = createDraftStore(); const archive = createReceiptArchive();
  const workspace = createWorkspace({ store, archive, timers, onSaved, renderDocument: x => documents.push(x), renderStatus: x => statuses.push(x), renderSubmission: x => notices.push(x) });
  return { pending, store, archive, workspace, statuses, documents, notices, fire() { const jobs = [...pending.values()]; pending.clear(); jobs.forEach(fn => fn()); } };
}
{
  const r = rig(); r.workspace.open('a'); r.workspace.edit('1'); r.workspace.edit('2'); assert.equal(r.store.read('a'), ''); assert.equal(r.pending.size, 1); r.fire(); assert.equal(r.store.read('a'), '2'); r.workspace.edit('3'); r.fire(); assert.equal(r.store.read('a'), '3'); r.workspace.edit('4'); r.workspace.close(); assert.equal(r.store.read('a'), '4'); assert.equal(r.statuses.length, 2);
}
{
  let r; r = rig((event, nav) => { if (event.text === 'one') nav.open('b'); }); r.workspace.open('a'); r.workspace.edit('one'); r.workspace.open('c'); assert.equal(r.documents.at(-1).id, 'b'); assert.equal(r.store.read('a'), 'one');
}
{
  let r; r = rig((event, nav) => { if (event.text === 'snapshot') { nav.open('b'); nav.edit('later'); } }); r.workspace.open('a'); r.workspace.edit('snapshot'); const receipt = r.workspace.submit(); assert.deepEqual(receipt, {id:'a', text:'snapshot'}); assert.equal(r.notices.at(-1), null); assert.equal(r.store.read('a'), 'snapshot'); assert.equal(r.archive.list().length, 1);
}
console.log('checks passed');
EOF"

