/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { render } from './src/render-workspace.js';
import { createPresencePanel } from './src/presence-panel.js';
import { createPresenceChannel } from './src/channel.js';
import { createWorkspaceNavigation } from './src/workspace-navigation.js';
for (const mode of ['synchronous', 'deferred']) {
  assert.deepEqual(await render({token:'room', bootstrapMode:mode}), {
    presence:{events:['room:bootstrap','room:update']}, metrics:{events:['room:update']}
  });
}
const a=createPresenceChannel('a'), b=createPresenceChannel('b');
const seen=[];
const nav=createWorkspaceNavigation((value,n)=>{seen.push(value); if(value==='a:bootstrap') n.select(b);});
nav.select(a);
a.emitUpdate(); b.emitUpdate();
assert.deepEqual(seen,['a:bootstrap','b:bootstrap','b:update']);
nav.hide(); b.emitUpdate();
assert.equal(seen.length,3);
let resolve;
const asyncChannel=createPresenceChannel('async',{decode:value=>new Promise(r=>{resolve=()=>r(value);})});
const later=[];
const panel=createPresencePanel(value=>later.push(value));
panel.show(asyncChannel);
panel.close();
resolve();
await Promise.resolve();
assert.deepEqual(later,[]);
console.log('presence checks passed');
EOF"

